def fetch_api(endpoint: str, params: Optional[dict] = None):
    """Phase-1 API fetch — rides the SAME shared ladder as Phase 2 [T1.3].

    ``_get_fetch_json`` carries ``detect_soft_block`` + real tier escalation
    on one persistent session. Returns the parsed payload, a SoftBlock
    signal (challenge served as 200 — falsy on purpose), or None when every
    tier failed. Falls back to a bare GET only when the image predates the
    module.
    """
    url = f"{API_BASE_URL}{endpoint}"
    try:
        return _get_fetch_json()(url, params=params)
    except ImportError:
        logger.warning("src.http_fetch unavailable — falling back to a bare GET")
        try:
            response = requests.get(url, params=params, headers=API_HEADERS, timeout=15)
            response.raise_for_status()
            return response.json()
        except Exception as e:
            logger.error(f"API request failed: {e}")
            return None


# ── FIELD NORMALIZERS — inline on purpose, NOT a src import ──────────────────
# Drafts execute in the browser-service image: a NEW src import would ImportError
# there until that image is rebuilt, so the ~25 lines live in each python-side
# template verbatim (playwright/UC normalize in-page via JS and don't need them).

def _norm_price(value) -> Optional[float]:
    """Strip currency symbols/whitespace from a price.

    "£1,234.56" → 1234.56 (a float), "1.234,56 €" → 1234.56, 24.99 (a
    JSON-LD number) → 24.99. Returns None when no digits are present — an
    unparseable price is EMPTY, never zero (0 would read as a real product
    priced at nothing). The currency stays in its own ``currency`` field.
    """
    if value is None:
        return None
    cleaned = re.sub(r"[^\d.,-]", "", str(value).strip())
    if not re.search(r"\d", cleaned):
        return None
    if "," in cleaned and "." in cleaned:
        # Both separators present: whichever comes LAST is the decimal one.
        if cleaned.rfind(",") > cleaned.rfind("."):
            cleaned = cleaned.replace(".", "").replace(",", ".")
        else:
            cleaned = cleaned.replace(",", "")
    elif "," in cleaned:
        # "1,234" (grouping) vs "1,5" (decimal comma): a comma followed by
        # exactly three digits is grouping, anything else is a decimal comma.
        cleaned = re.sub(r",(?=\d{3}(?:\D|$))", "", cleaned).replace(",", ".")
    try:
        return float(cleaned)
    except ValueError:
        return None


def _norm_availability(value) -> Optional[str]:
    """Normalize availability to ``in_stock`` / ``out_of_stock``.

    Accepts the schema.org URI form, InStock / In Stock / in_stock / Available
    and their negatives. Anything unrecognised passes through lowercased —
    availability is never invented (an unknown state is data, not an error).
    """
    if value is None:
        return None
    if isinstance(value, bool):
        return "in_stock" if value else "out_of_stock"
    text = str(value).strip().lower()
    if not text:
        return None
    if "://" in text:  # e.g. http://schema.org/InStock
        text = text.rsplit("/", 1)[-1]
    compact = text.replace("-", "_").replace(" ", "")
    if compact in ("in_stock", "instock", "available"):
        return "in_stock"
    if compact in ("out_of_stock", "outofstock", "unavailable", "sold_out", "soldout"):
        return "out_of_stock"
    return text


def _product_handle(url: str) -> str:
    """Code Writer adapted: extract the Shopify handle from any product URL."""
    m = PRODUCT_HANDLE_RE.search(url or "")
    return m.group(1) if m else ""


def _set_listing_endpoint(listing_url: str) -> str:
    """Code Writer adapted: resolve the Phase-1 Shopify JSON endpoint from the
    listing URL (--listing-url / SCRAPER_LISTING_URL / promoted default).
    A /collections/{handle} listing maps to its products.json; anything else
    falls back to the full-catalog /products.json."""
    global API_PRODUCTS_ENDPOINT, ACTIVE_LISTING_URL
    listing = (listing_url or "").strip() or DEFAULT_LISTING_URL
    ACTIVE_LISTING_URL = listing
    path = urlparse(listing).path or "/"
    m = re.search(r"/collections/([a-z0-9-]+)", path)
    if m:
        endpoint = f"/collections/{m.group(1)}/products.json"
    elif path.endswith("products.json"):
        endpoint = path
    else:
        endpoint = CATALOG_ENDPOINT
    API_PRODUCTS_ENDPOINT = endpoint
    return endpoint


def transform_api_product(api_product: dict, index: int, src_url: str) -> dict:
    """Code Writer adapted: Frank Body (Shopify) field map — user-requested
    fields ONLY (product name, price, currency, availability) + bookkeeping.

    PRIMARY (.json): variants[*].price is a decimal STRING in major units
    ('18.00') — run through _norm_price, multi-variant products aggregate to
    min(variants[*].price). Currency is the payload's price_currency ('AUD',
    verified live). Availability: in_stock when ANY variant is sellable.
    """
    data = api_product if isinstance(api_product, dict) else {}
    product = data.get("product") or data  # .json wraps in {"product": ...}; .js is flat
    variants = product.get("variants") or []

    prices: list[float] = []
    currency = ""
    any_sellable: Optional[bool] = None
    for v in variants:
        if not isinstance(v, dict):
            continue
        p = _norm_price(v.get("price"))
        if p is not None:
            prices.append(p)
        if not currency:
            currency = str(v.get("price_currency") or v.get("currency") or "").strip().upper()
        # Code Writer adapted: this store's .json omits the `available` boolean,
        # so sellability falls back to Shopify's own availability rule — a
        # variant is sellable when its inventory is UNTRACKED (no
        # inventory_management), its policy is 'continue' (sell when out of
        # stock), or tracked stock is > 0. An explicit boolean, when present,
        # wins for that variant.
        if isinstance(v.get("available"), bool):
            sellable: Optional[bool] = v["available"]
        else:
            tracked = v.get("inventory_management") not in (None, "", "null")
            qty = v.get("inventory_quantity")
            sellable = (
                not tracked
                or str(v.get("inventory_policy") or "").lower() == "continue"
                or (isinstance(qty, (int, float)) and qty > 0)
            )
        if sellable is not None:
            any_sellable = bool(any_sellable) or bool(sellable)
    price = min(prices) if prices else _norm_price(product.get("price"))
    if not currency:
        currency = str(product.get("price_currency") or product.get("currency") or "").strip().upper()
    if any_sellable is None and isinstance(product.get("available"), bool):
        any_sellable = product["available"]
    availability = _norm_availability(any_sellable)

    handle = product.get("handle") or _product_handle(src_url)
    url = urljoin(SITE_URL, f"/products/{handle}") if handle else (product.get("url") or src_url)

    return {
        "id": index,
        "title": (product.get("title") or "").strip(),
        # Symbol-free numeric price: baking "$" into the field makes every
        # downstream numeric comparison (and currency inference) wrong.
        "price": price,
        "currency": currency,
        "availability": availability,
        "url": url,
        "src_url": src_url,
        "status_code": 200,
        "scraped_at": datetime.now(timezone.utc).isoformat(),
        "remarks": "",
    }


def transform_api_jobs(raw_jobs: list[dict], src_url: str = "") -> list[dict]:
    """JOB boards: map raw API items to standard job fields using the GENERIC
    resolver in ``src.job_fields``.  Do NOT hardcode site-specific field names —
    ``map_jobs`` infers each field's source path (title, company, location,
    description, salary, job_type, posted_date, apply_url, requirements) by
    coverage over the batch, so the SAME code works across job platforms.
    Use this in place of ``transform_api_product`` when scraping job postings.
    """
    from src.job_fields import map_jobs

    if not raw_jobs:
        return []
    jobs = map_jobs(sample_items=raw_jobs, raw_items=raw_jobs)
    now = datetime.now(timezone.utc).isoformat()
    for idx, j in enumerate(jobs, start=1):
        j.setdefault("id", idx)
        if src_url:
            j.setdefault("src_url", src_url)
        j.setdefault("status_code", 200)
        j.setdefault("scraped_at", now)
        j.setdefault("remarks", "")
    return jobs


def fetch_all_products_via_api() -> tuple[list[str], list[dict]]:
    all_products = []
    offset = 0
    cursor = None
    page = 1

    # [T0.5] Why discovery stopped — emitted as metadata.discovery_coverage
    # so the tester's coverage gate and the execution-time strategy+tier
    # recycle can tell an anti-bot wall from a genuine catalog end.
    # Vocabulary matches the FAIL-class set the gates know:
    #   empty_first_page — a 200 challenge wall yielded zero items (job-58)
    #   navigate_error   — the ladder was exhausted / transport failure
    #   no_next_link     — normal exhaustion (short page / total / cursor end)
    global _DISCOVERY_META, API_PRODUCTS_ENDPOINT
    _DISCOVERY_META = {
        "stop_reason": "no_next_link",
        "ran_phase1": True,
        "skipped_reason": "",
        "discovered_urls": 0,
        "pages_fetched": 0,
        "soft_block_escalations": 0,
        "max_pages_hit": False,
    }

    logger.info(
        f"Discovering via {API_BASE_URL}{API_PRODUCTS_ENDPOINT} "
        f"(listing: {ACTIVE_LISTING_URL})"
    )

    while True:
        if PAGINATION_TYPE == "offset":
            params = {"limit": PAGE_SIZE, "offset": offset}
        elif PAGINATION_TYPE == "page":
            params = {"limit": PAGE_SIZE, "page": page}
        elif PAGINATION_TYPE == "cursor":
            params = {"limit": PAGE_SIZE, "cursor": cursor} if cursor else {"limit": PAGE_SIZE}
        else:
            params = {"limit": PAGE_SIZE}

        logger.info(f"Fetching API page {page}: {API_PRODUCTS_ENDPOINT}")
        result = fetch_api(API_PRODUCTS_ENDPOINT, params=params)

        # fetch_api contract [T1.3]: (payload, status) on success, SoftBlock
        # on a challenge-served-as-200, None when every tier failed.
        if isinstance(result, SoftBlock):
            logger.error(
                f"Discovery page {page}: challenge served as 200 "
                f"({getattr(result, 'reason', '?')}) — every ladder tier "
                f"returned a challenge"
            )
            _DISCOVERY_META["soft_block_escalations"] += 1
            # A wall yielding zero items is the job-58 shape, not a
            # catalog end — only page 1's wall sets the zero-URL reason.
            if page == 1:
                _DISCOVERY_META["stop_reason"] = "empty_first_page"
            break
        if not result:
            logger.error(f"Discovery page {page}: every ladder tier failed")
            if page == 1:
                _DISCOVERY_META["stop_reason"] = "navigate_error"
            break

        data = result[0]
        _DISCOVERY_META["pages_fetched"] = page

        if not data:
            break

        products = data.get("products", []) or data.get("items", []) or data.get("data", [])
        if isinstance(data, list):
            products = data

        for raw in products:
            all_products.append(raw)

        logger.info(f"Page {page}: {len(products)} products (total: {len(all_products)})")

        # Stop when a page is short (exhausted) OR we've hit the API's reported total.
        if len(products) < PAGE_SIZE:
            break
        total = (
            data.get("totalCount") or data.get("total_count") or data.get("count")
            or data.get("total") or data.get("totalResults") or data.get("totalJobs")
        )
        if isinstance(total, int) and total > 0 and len(all_products) >= total:
            break

        if PAGINATION_TYPE == "cursor":
            cursor = data.get("next_cursor") or data.get("cursor")
            if not cursor:
                break
        elif PAGINATION_TYPE == "offset":
            offset += PAGE_SIZE
        # page-based: single increment below (do NOT increment twice)
        page += 1

    # Code Writer adapted: Shopify rows carry a `handle`, not a `url` — build
    # canonical absolute /products/{handle} URLs via urljoin (never string
    # concatenation onto a base path).
    urls: list[str] = []
    seen: set[str] = set()
    for p in all_products:
        row = p if isinstance(p, dict) else {}
        handle = row.get("handle") or _product_handle(row.get("url", "") or "")
        if not handle:
            continue
        u = urljoin(SITE_URL, f"/products/{handle}")
        if u in seen:
            continue
        seen.add(u)
        urls.append(u)
    _DISCOVERY_META["discovered_urls"] = len(urls)

    # Zero-yield self-heal: a missing/empty collection endpoint must not end
    # the run at 0 item URLs — retry ONCE against the full-catalog endpoint.
    if not urls and API_PRODUCTS_ENDPOINT != CATALOG_ENDPOINT:
        logger.warning(
            f"0 item URLs from {API_BASE_URL}{API_PRODUCTS_ENDPOINT} — "
            f"retrying once with {CATALOG_ENDPOINT}"
        )
        API_PRODUCTS_ENDPOINT = CATALOG_ENDPOINT
        return fetch_all_products_via_api()

    return urls, all_products


