try:  # guarded: the browser-service image may predate src.http_fetch
    from src.http_fetch import SoftBlock  # noqa: E402
except ImportError:  # pragma: no cover
    class SoftBlock:  # type: ignore[no-redef]
        """Image predates the shared module — no signal can ever occur."""

        def __init__(self, *a, **k):
            self.reason = "unavailable"

        def __bool__(self):
            return False


def _get_fetch_json():
    global _FETCH_JSON
    if _FETCH_JSON is None:
        from src.http_fetch import create_fetch_json

        _FETCH_JSON = create_fetch_json(
            delay_s=DELAY_BETWEEN_REQUESTS, headers=API_HEADERS
        )
    return _FETCH_JSON


def _product_json_url(url: str) -> str:
    """Code Writer adapted: map a product page URL to its .json endpoint."""
    if url.endswith(".json") and "/products/" in url:
        return url
    handle = _product_handle(url)
    if not handle:
        return url  # let the fetch fail loudly and be logged
    return urljoin(SITE_URL, f"/products/{handle}.json")


def _product_js_url(url: str) -> str:
    """Code Writer adapted: the .js fallback endpoint for the same handle."""
    if url.endswith(".json") and "/products/" in url:
        return url[: -len(".json")] + ".js"
    handle = _product_handle(url)
    if not handle:
        return url
    return urljoin(SITE_URL, f"/products/{handle}.js")


def _fetch_json_or_none(url: str):
    """Code Writer adapted: one ladder fetch -> (payload, status) | None.

    Every HTTP call rides the shared ladder (proxy path preserved); the bare
    GET exists only when the execution image predates src.http_fetch.
    """
    try:
        return _get_fetch_json()(url)
    except ImportError:
        logger.warning("src.http_fetch unavailable — falling back to a bare GET")
    except Exception as e:
        logger.error(f"Request failed for {url}: {e}")
        return None
    try:
        response = requests.get(url, headers=API_HEADERS, timeout=15)
        response.raise_for_status()
        return (response.json(), response.status_code)
    except Exception as e:
        logger.error(f"Request failed for {url}: {e}")
        return None


def _record_from_payload(data, status: int, src_url: str, api_url: str = "") -> Optional[dict]:
    """Code Writer adapted: map a fetched payload to the output record.

    .json shape: {"product": {...}} — decimals + price_currency, used as-is.
    .js shape (FALLBACK): flat object, price in CENTS — divide by 100 before
    mapping; .js exposes NO currency, so that stays empty and is noted.
    """
    if not isinstance(data, dict):
        return None
    product = data.get("product")
    if isinstance(product, dict) and product:
        record = transform_api_product(data, 0, src_url)
        record["status_code"] = status
        # Code Writer adapted: if .json yielded no derivable availability, top
        # up from the flat .js endpoint for the same handle (its `available`
        # boolean is verified on this store).
        if record.get("availability") is None and api_url:
            js_result = _fetch_json_or_none(_product_js_url(api_url))
            if isinstance(js_result, (tuple, list)) and len(js_result) == 2:
                js = js_result[0] if isinstance(js_result[0], dict) else {}
                if isinstance(js.get("available"), bool):
                    record["availability"] = _norm_availability(js["available"])
        return record
    if data.get("title"):  # flat .js payload
        js = dict(data)
        for key in ("price", "price_min", "price_max"):
            if isinstance(js.get(key), int):
                js[key] = round(js[key] / 100.0, 2)
        for v in js.get("variants") or []:
            if isinstance(v, dict) and isinstance(v.get("price"), int):
                v["price"] = round(v["price"] / 100.0, 2)
        record = transform_api_product({"product": js}, 0, src_url)
        record["status_code"] = status
        if not record.get("currency"):
            record["remarks"] = "currency absent on .js fallback payload"
        return record
    return None


def scrape_product(url: str, src_url: str) -> Optional[dict]:
    """Phase-2 item fetch: GET /products/{handle}.json (field map PRIMARY).

    Falls back to /products/{handle}.js (price in CENTS -> /100) when the
    .json endpoint yields nothing. No payload from either endpoint is a soft
    404 — the item is logged and dropped, never fabricated.
    """
    try:
        time.sleep(DELAY_BETWEEN_REQUESTS)
        api_url = _product_json_url(url)
        result = _fetch_json_or_none(api_url)
        if isinstance(result, SoftBlock):
            logger.error(f"Challenge served for {url} ({getattr(result, 'reason', '?')})")
            return None
        if not result:
            result = _fetch_json_or_none(_product_js_url(url))
        if isinstance(result, SoftBlock):
            logger.error(f"Challenge served for {url} ({getattr(result, 'reason', '?')})")
            return None
        if not result:
            logger.warning(f"Soft 404: product not found ({url}) — no JSON from .json/.js")
            return None
        data, status = result
        record = _record_from_payload(data, status, src_url, api_url=api_url)
        if record is None:
            logger.warning(
                f"Soft 404: product not found ({url}) — HTTP {status} payload had no product"
            )
            return None
        return record
    except Exception as e:
        logger.error(f"Failed to scrape {url}: {e}")
        return None


