def _build_output(results: list, failed: int, start_time: float, phase: str,
                  discovered_raw: int) -> dict:
    """Code Writer adapted: single output builder (extraction + discovery-only)
    with the coverage block the tester's gates read."""
    return {
        "site": {
            "name": SITE_NAME,
            "url": SITE_URL,
            "platform": PLATFORM,
            "scraping_method": SCRAPING_METHOD,
            "scraped_at": datetime.now(timezone.utc).isoformat(),
        },
        "products": results,
        "metadata": {
            # job-76 myhouse: lets every consumer tell a discovery artifact
            # (URL stubs, no fields) from an extraction result.
            "phase": phase,
            "scraping_duration_seconds": round(time.time() - start_time, 2),
            "failed_products": failed,
            "rate_limit_delay": DELAY_BETWEEN_REQUESTS,
            "discovered_urls": discovered_raw,
            "pages_fetched": _DISCOVERY_META.get("pages_fetched", 0),
            "total_discovered": _DISCOVERY_META.get("discovered_urls", 0),
            # [T0.5] Always emitted so the gates read a uniform schema
            # regardless of which path produced the output.
            "discovery_coverage": {
                **_DISCOVERY_META,
                "found": len(results),
            },
        },
    }


def _write_output(output: dict) -> None:
    with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
        json.dump(output, f, indent=2, ensure_ascii=False)


# ═══════════════════════════════════════════════════════════════════════════════
# MAIN
# ═══════════════════════════════════════════════════════════════════════════════

# ── CLI CONTRACT — keep every line below when adapting ───────────────────────
# The pipeline launches this scraper with EXACTLY these names. A flag missing
# from the argparse below is STRIPPED at launch and discovery silently falls
# back to the seed file (input_urls.json). ADD flags if you need them; NEVER
# remove or rename:
#   --fresh-discovery  the ONLY discovery trigger for the api family (execution
#                      always passes it) — there is NO listing page; discovery
#                      IS the API. SCRAPER_LISTING_URL / SCRAPER_FORCE_DISCOVERY
#                      are the env gates.
#   --discover-only    discovery flag: Phase 1 MUST run and re-discover.
#   --listing-url      discovery flag: listing/collection URL to discover from.
#   --input/--sample/--limit  testing
# Source of truth: webapp/agents/constants.py
# ──────────────────────────────────────────────────────────────────────────────
def main():
    parser = argparse.ArgumentParser(description=f"API scraper for {SITE_NAME}")
    parser.add_argument("--sample", action="store_true", help="Scrape only 5 products")
    parser.add_argument("--limit", type=int, default=None, help="Max products to scrape")
    parser.add_argument("--input", type=str, default=None, help="Path to input URLs JSON file")
    parser.add_argument("--urls", nargs="+", default=None, help="Product URLs as arguments")
    parser.add_argument("--fresh-discovery", action="store_true",
                        help="Bypass input_urls.json and rediscover via API pagination")
    # Code Writer adapted: hard-contract discovery flags for this list_page job.
    parser.add_argument("--discover-only", action="store_true",
                        help="Run Phase 1 discovery only: re-discover, save URLs, skip extraction")
    parser.add_argument("--listing-url", type=str, default=None,
                        help="Listing/collection URL to discover from (falls back to SCRAPER_LISTING_URL)")
    parser.add_argument("--no-proxy", action="store_true",
                        help="Force direct HTTP (no proxy tiers) — already the default for this site")
    args = parser.parse_args()

    if args.input:
        # [job-60 zquiet] The runner's CWD is not the scraper's directory
        # (the tester passes `--input input_urls.json` while CWD=/app), so a
        # relative seed-file value must resolve against the scraper's own
        # directory. os.path.join passes absolute paths through untouched.
        args.input = os.path.join(SCRIPT_DIR, args.input)

    # HARD CONTRACT: env listing read BEFORE the seed-file gate — execution
    # sets SCRAPER_LISTING_URL, not a CLI flag. It selects the Phase-1
    # endpoint (collection products.json) and forces fresh discovery.
    _env_listing = os.environ.get("SCRAPER_LISTING_URL", "").strip()
    _resolved = _set_listing_endpoint(args.listing_url or _env_listing)

    start_time = time.time()

    logger.info("=" * 80)
    logger.info(f"Starting API scraper for {SITE_NAME}")
    logger.info(f"Site: {SITE_URL}")
    logger.info(f"API: {API_BASE_URL}{API_PRODUCTS_ENDPOINT} (listing: {ACTIVE_LISTING_URL})")
    if args.no_proxy:
        logger.info("--no-proxy: direct HTTP only (no proxy tiers) — default for this site")
    logger.info(f"Output: {OUTPUT_FILE}")
    logger.info("=" * 80)

    product_urls = []
    raw_products = []
    src_url = f"{API_BASE_URL}{API_PRODUCTS_ENDPOINT}"
    _from_seed = False

    # F6: run_execution always passes --fresh-discovery for nav jobs; declaring
    # it here means the CLI-contract guard passes it through (declared flags
    # are never stripped) and the seed-file branch can't suppress API
    # pagination. --discover-only is a discovery flag too: when passed, Phase 1
    # MUST run and re-discover regardless of any seed file [jobs 359/360].
    _force_fresh = (
        args.fresh_discovery
        or args.discover_only
        or bool(_env_listing)
        or bool(os.environ.get("SCRAPER_FORCE_DISCOVERY", "").strip())
    )
    if args.urls and not _force_fresh:
        product_urls = args.urls
        _from_seed = True
    elif args.input and not _force_fresh:
        product_urls = load_urls_from_file(args.input)
        _from_seed = True
    elif os.path.exists(INPUT_FILE) and not _force_fresh:
        product_urls = load_urls_from_file(INPUT_FILE)
        _from_seed = True
    else:
        logger.info(
            "Fresh discovery (%s): paginating Shopify listing JSON %s",
            "flag" if (args.fresh_discovery or args.discover_only) else "env",
            _resolved,
        )
        product_urls, raw_products = fetch_all_products_via_api()
        save_urls_to_file(INPUT_FILE, product_urls)
        # Re-resolve: the zero-yield self-heal may have switched the endpoint.
        src_url = f"{API_BASE_URL}{API_PRODUCTS_ENDPOINT}"
        # Code Writer adapted: decimal price + price_currency are verified ONLY
        # on the per-item /products/{handle}.json payload (listing rows carry
        # integer cents and no currency) — drop the rows so Phase 2 fetches
        # every item uniformly through scrape_product().
        raw_products = []

    # [T0.5] Raw pre-cut count — --sample/--limit truncate product_urls below,
    # and the coverage block must report what DISCOVERY found, not what
    # survived the sampling.
    discovered_urls_raw = len(product_urls)

    if args.discover_only:
        save_urls_to_file(INPUT_FILE, product_urls)
        output = _build_output([], 0, start_time, "discovery", discovered_urls_raw)
        _write_output(output)
        logger.info(
            f"Discovery-only complete: {discovered_urls_raw} URLs via "
            f"{API_BASE_URL}{API_PRODUCTS_ENDPOINT} -> {OUTPUT_FILE}"
        )
        return

    if args.sample:
        product_urls = product_urls[:5]
    if args.limit:
        product_urls = product_urls[: args.limit]

    logger.info(f"Total products to scrape: {len(product_urls)}")

    results = []
    failed = 0

    if raw_products and len(raw_products) == len(product_urls):
        for i, raw in enumerate(raw_products[: len(product_urls)]):
            try:
                product = transform_api_product(raw, i + 1, src_url)
                results.append(product)
            except Exception as e:
                logger.error(f"Error transforming product {i + 1}: {e}")
                failed += 1
    else:
        for i, url in enumerate(product_urls):
            try:
                # src_url discipline: seeded items carry their own URL;
                # discovered items carry the listing/API query URL.
                item_src = url if _from_seed else src_url
                product = scrape_product(url, item_src)
                if product and product.get("title") and (
                    product.get("price") is not None or product.get("availability")
                ):
                    product["id"] = i + 1
                    results.append(product)
                else:
                    # Output contract: drop items missing title + a core field
                    # (soft-404 stubs land here — logged, never emitted).
                    failed += 1
                    if product:
                        logger.warning(
                            f"Dropped {url}: {product.get('remarks') or 'missing title/price'}"
                        )
                    else:
                        logger.warning(f"Dropped {url}: fetch failed (possible soft 404)")
            except Exception as e:
                logger.error(f"Error processing {url}: {e}")
                failed += 1

            if (i + 1) % 25 == 0:
                percent = ((i + 1) / len(product_urls)) * 100
                logger.info(f"Progress: [{i + 1}/{len(product_urls)}] ({percent:.1f}%)")

    output = _build_output(results, failed, start_time, "extraction", discovered_urls_raw)
    _write_output(output)

    logger.info("=" * 80)
    logger.info("EXTRACTION COMPLETE")
    logger.info(f"Total: {len(results)}, Failed: {failed}")
    logger.info(f"Duration: {round(time.time() - start_time, 2)}s")
    logger.info(f"Output: {OUTPUT_FILE}")
    logger.info("=" * 80)


if __name__ == "__main__":
    main()
